package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"mvdan.cc/sh/v3/interp"
	"mvdan.cc/sh/v3/syntax"
)

func runSnippet(parser *syntax.Parser, runner *interp.Runner, code string) error {
	file, err := parser.Parse(strings.NewReader(code), "")
	if err != nil {
		return fmt.Errorf("parse: %w", err)
	}
	return runner.Run(nil, file)
}

func main() {
	base := filepath.Join("/workspace", ".tmp_probe", "go_mvdan", "state")
	_ = os.MkdirAll(filepath.Join(base, "subdir"), 0o755)

	parser := syntax.NewParser()
	runner, err := interp.New(
		interp.Dir(base),
		interp.Env(expandListEnviron("PROBE_INITIAL=1")),
		interp.StdIO(nil, os.Stdout, os.Stderr),
	)
	if err != nil {
		panic(err)
	}

	snippets := []string{
		"pwd",
		"cd subdir",
		"pwd",
		"FOO=bar; export FOO",
		"echo $FOO",
		"alias hi='echo alias-ok'",
		"hi",
		"nosuchcommand",
		"printf '%s\n' \"unterminated",
		"exit 7",
		"echo after-exit",
	}

	for i, code := range snippets {
		fmt.Printf("=== snippet %d ===\n%s\n", i+1, code)
		err := runSnippet(parser, runner, code)
		if err != nil {
			fmt.Printf("ERR: %T: %v\n", err, err)
		} else {
			fmt.Println("OK")
		}
	}
}

func expandListEnviron(extra ...string) expandList {
	return expandList(append(os.Environ(), extra...))
}

type expandList []string

func (l expandList) Each(fn func(name string, vr interp.Variable) bool) {
	for _, kv := range l {
		name, value, ok := strings.Cut(kv, "=")
		if !ok {
			continue
		}
		if !fn(name, interp.Variable{Set: true, Exported: true, Kind: interp.String, Str: value}) {
			return
		}
	}
}

